var contextTags = context.get("tags") || {};
var message = msg.payload;
var match = message.match(/antenne (\w) : ([0-9A-F]+)/);

if (!match) return null;

var antenne = match[1]; // "A" ou "B"
var tagId = match[2];    // ID du tag

// Correction du fuseau horaire
var now = new Date();
var timezoneOffset = 1;
now.setHours(now.getHours() + timezoneOffset);

var timestamp = now.toISOString().slice(0, 19).replace('T', ' ');

// Vérifier l'historique
var lastRecord = contextTags[tagId];
if (lastRecord) {
    var lastAntenna = lastRecord.antenne;
    var direction = "";

    if (lastAntenna === "A" && antenne === "B") {
        direction = "⬆️ Sortie";
    } else if (lastAntenna === "B" && antenne === "A") {
        direction = "⬇️ Entrée";
    } else {
        return null; // Ignorer détection erronée
    }

    msg.payload = {
        tag_id: tagId,
        direction: direction,
        timestamp: timestamp
    };
}

// Sauvegarde de la dernière détection
contextTags[tagId] = { antenne, timestamp };
context.set("tags", contextTags);

return msg;

var data = msg.payload;

// Debug pour voir les données reçues
node.warn("🔍 Données reçues dans Lien Table / données : " + JSON.stringify(data));

// Vérifier si toutes les données sont présentes (on n'arrête plus le message)
if (!data.tag_id || !data.direction || !data.timestamp) {
    node.error("⚠️ Données manquantes, mais on envoie quand même au Dashboard", msg);
}

// Vérifier si `nom_equipement` est défini, sinon mettre "Aucun matériel associé"
if (!data.nom_equipement) {
    data.nom_equipement = "Aucun matériel associé";
}

// Récupération de l'historique
var history = context.get("history") || [];

// Construire l'entrée mise à jour
var entry = {
    tag_id: data.tag_id,
    direction: data.direction,
    timestamp: data.timestamp,
    nom_equipement: data.nom_equipement
};

// Debug avant envoi
node.warn("🚀 Données FINALES envoyées au Dashboard : " + JSON.stringify(entry));

// Ajouter à l'historique
history.push(entry);

// Garder uniquement les 48 dernières heures
var cutoff = new Date();
cutoff.setHours(cutoff.getHours() - 48);
history = history.filter(item => new Date(item.timestamp) > cutoff);

// Sauvegarde de l'historique
context.set("history", history);

// **Envoyer les données au Dashboard (toujours)**
msg.payload = history;
return msg;

var data = msg.payload;

// Vérifier que toutes les données sont présentes
if (!data.tag_id || !data.direction || !data.timestamp) {
    node.error("Données manquantes pour l'insertion SQL", msg);
    return null;
}

// Construction de la requête SQL
msg.topic = `INSERT INTO tag_logs (tag_id, direction, timestamp) VALUES ('${data.tag_id}', '${data.direction}', '${data.timestamp}');`;

// Debug pour voir la requête
node.warn("🔍 Requête SQL envoyée : " + msg.topic);

return msg;

// Sauvegarde du contexte avant la requête
msg.tag_id = msg.payload.tag_id;
msg.direction = msg.payload.direction;
msg.timestamp = msg.payload.timestamp;

// Vérification que le Tag ID existe
if (!msg.tag_id) {
    node.error("Tag ID manquant", msg);
    return null;
}

// Requête SQL mise à jour pour récupérer le nom de l’équipement,
// son autorisation de sortie, et les informations utilisateur associées
msg.topic = `
    SELECT tag_id, nom_equipement, autorisation_sortie, user_prenom, user_nom
    FROM equipements
    WHERE LOWER(tag_id) = LOWER('${msg.tag_id}')
    LIMIT 1;
`;

// Debug
node.warn("🔍 Requête SQL envoyée : " + msg.topic);

return msg;

// Récupérer l'historique stocké dans le contexte (historique des 48h)
var history = context.get("history") || [];

// Vérifier que la réponse SQL contient bien un équipement et une autorisation de sortie
let newEntry;
if (Array.isArray(msg.payload) && msg.payload.length > 0) {
    var equipement = msg.payload[0];

    // Déterminer l'autorisation en fonction de la direction
    var autorisation;
    if (msg.direction.includes("Sortie")) {
        autorisation = equipement.autorisation_sortie === 1 ? "✅ Autorisé" : "❌ Interdit";
    } else if (msg.direction.includes("Entrée")) {
        autorisation = "✅ Autorisé";
    } else {
        autorisation = "❓ Inconnu";
    }

    newEntry = {
        tag_id: msg.tag_id || "Inconnu",
        direction: msg.direction || "Inconnue",
        timestamp: msg.timestamp || new Date().toISOString().slice(0, 19).replace('T', ' '),
        nom_equipement: equipement.nom_equipement?.trim() || "Aucun matériel associé",
        autorisation_sortie: autorisation,
        user_prenom: equipement.user_prenom || null,
        user_nom: equipement.user_nom || null
    };
} else {
    newEntry = {
        tag_id: msg.tag_id || "Inconnu",
        direction: msg.direction || "Inconnue",
        timestamp: msg.timestamp || new Date().toISOString().slice(0, 19).replace('T', ' '),
        nom_equipement: "Aucun matériel associé",
        autorisation_sortie: "❌ Interdit",
        user_prenom: null,
        user_nom: null
    };
}

// Ajouter la nouvelle entrée à l'historique
history.push(newEntry);

// 🔍 Nettoyage de l'historique : ne garder que les 48 dernières heures
var cutoff = new Date();
cutoff.setHours(cutoff.getHours() - 48);
history = history.filter(item => new Date(item.timestamp) > cutoff);

// Sauvegarder l'historique mis à jour dans le contexte
context.set("history", history);

// Envoyer l'historique complet au Dashboard
msg.payload = history;

// Debug avant envoi au Dashboard et à l'alerte mail
node.warn("📜 Données finales envoyées au Dashboard : " + JSON.stringify(msg.payload));

return msg;

var history = msg.payload;
var cutoff = new Date();
cutoff.setHours(cutoff.getHours() - 48);

var sortiesGlobales = history.filter(entry => {
    let d = new Date(entry.timestamp);
    return d > cutoff && entry.direction.toLowerCase().includes("sortie");
});

msg.payload = sortiesGlobales.length;
return msg;

var history = msg.payload;
var cutoff = new Date();
cutoff.setHours(cutoff.getHours() - 48);

var sortiesInterdites = history.filter(entry => {
    let d = new Date(entry.timestamp);
    let isSortie = entry.direction.toLowerCase().includes("sortie");
    let isInterdit = entry.autorisation_sortie && entry.autorisation_sortie.includes("❌");
    return d > cutoff && isSortie && isInterdit;
});

msg.payload = sortiesInterdites.length;
return msg;

const messages = [];

for (const item of msg.payload) {
    if (item.autorisation_sortie === "❌ Interdit") {
        const prenom = item.user_prenom?.toLowerCase() || "utilisateur";
        const nom = item.user_nom?.toLowerCase() || "inconnu";
        const email = `${prenom}.${nom}@lde.fr`;

        // Mail au collaborateur
        messages.push({
            to: email,
            from: "rfid.lde@gmail.com",
            topic: "🔒 ALERTE - Sortie non autorisée détectée",
            payload:
                `Bonjour ${prenom} ${nom},

Notre système de contrôle RFID a détecté une sortie de matériel non autorisée.

ℹ️ Équipement : ${item.nom_equipement}
🔖 Tag ID : ${item.tag_id}
📅 Date de sortie : ${item.timestamp}

Conformément à nos règles de sécurité informatique, cet équipement n'est pas autorisé à sortir des locaux.
Merci de bien vouloir le ramener dans les plus brefs délais dès votre retour.

Si vous pensez qu'il s'agit d'une erreur, merci de contacter l’équipe IT.

Cordialement,
— Système de contrôle RFID LDE`
        });

        // Mail au support IT (Enzo)
        messages.push({
            to: "Enzo.storck@lde.fr",  // <- adresse IT temporaire
            from: "rfid.lde@gmail.com",
            topic: "📣 IT - Alerte : sortie non autorisée",
            payload:
                `🔔 ALERTE : Sortie non autorisée détectée

Un matériel a quitté les locaux sans autorisation.

🧑‍💼 Collaborateur : ${prenom} ${nom} (${prenom}.${nom}@lde.fr)
💻 Équipement : ${item.nom_equipement}
🔖 Tag ID : ${item.tag_id}
📅 Date de sortie : ${item.timestamp}

Merci de consigner cette alerte et, si besoin, de prendre contact avec l’utilisateur.

— Système de contrôle RFID LDE`
        });
    }
}

return messages.length > 0 ? [messages] : null;

const history = msg.payload || [];

const alerts = history.filter(item =>
    item.direction.includes("Sortie") &&
    item.autorisation_sortie === "❌ Interdit"
);

msg.payload = alerts.length;
return msg;
